css:
.sim-validation-chapter { --ink: #1a1a1a; --muted: #666; --accent: #00CED1; --warm: #FFBF00; --line: #ddd; --paper: #f9f9f9; font-family: system-ui, -apple-system, sans-serif; color: var(--ink); background: var(--paper); padding: 2rem; max-width: 1200px; margin: 0 auto; }
.sim-header h2 { font-size: 1.8rem; margin-bottom: 0.5rem; font-weight: 700; }
.sim-lead { font-size: 1.1rem; color: var(--muted); max-width: 800px; margin-bottom: 2rem; }
.sim-controls { display: flex; gap: 2rem; margin-bottom: 2rem; flex-wrap: wrap; align-items: center; }
.control-group { display: flex; align-items: center; gap: 0.5rem; }
.control-group label { font-weight: 600; font-size: 0.95rem; }
#scene-select { padding: 0.4rem 0.8rem; font-size: 0.95rem; border: 1px solid var(--line); border-radius: 4px; background: #fff; }
.btn-reset { padding: 0.4rem 1rem; font-size: 0.9rem; background: var(--ink); color: #fff; border: none; border-radius: 4px; cursor: pointer; }
.btn-reset:hover { opacity: 0.9; }
.sim-content-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 2rem; }
@media (max-width: 900px) { .sim-content-grid { grid-template-columns: 1fr; } }
.sim-table-container, .sim-chart-container { background: #fff; border: 1px solid var(--line); border-radius: 8px; padding: 1.5rem; }
.sim-table-container h3, .sim-chart-container h3 { margin-top: 0; font-size: 1.2rem; margin-bottom: 1rem; }
.table-wrapper { max-height: 300px; overflow-y: auto; border: 1px solid var(--line); }
#mse-table { width: 100%; border-collapse: collapse; font-size: 0.9rem; }
#mse-table th, #mse-table td { padding: 0.5rem; text-align: right; border-bottom: 1px solid var(--line); }
#mse-table th { background: #f0f0f0; position: sticky; top: 0; }
#mse-table td:first-child, #mse-table th:first-child { text-align: left; font-weight: 600; }
#mse-table tr:hover td { background: #f5f9ff; }
.table-legend { display: flex; flex-wrap: wrap; gap: 1rem; margin-top: 1rem; font-size: 0.85rem; }
.legend-item { display: flex; align-items: center; gap: 0.4rem; }
.dot { width: 10px; height: 10px; border-radius: 50%; display: inline-block; }
.method-a { background: #ccc; }
.method-b { background: #999; }
.method-c { background: var(--accent); }
.method-d { background: #008b8b; }
.method-e { background: var(--ink); }
.cell-detail-panel { margin-top: 1rem; padding: 1rem; background: #f0f4f8; border-left: 4px solid var(--accent); font-size: 0.9rem; min-height: 3rem; }
#threshold-chart { width: 100%; height: auto; }
.chart-tooltip { position: absolute; background: rgba(0,0,0,0.8); color: #fff; padding: 0.4rem 0.6rem; border-radius: 4px; font-size: 0.8rem; pointer-events: none; opacity: 0; transition: opacity 0.2s; }
.chart-note { font-size: 0.85rem; color: var(--muted); margin-top: 0.5rem; font-style: italic; }
.sim-evidence-links { margin-top: 2rem; }
.sim-evidence-links h4 { font-size: 1rem; margin-bottom: 0.5rem; }
.evidence-grid { display: flex; gap: 1rem; }
.btn-source { padding: 0.3rem 0.8rem; font-size: 0.85rem; border: 1px solid var(--line); background: #fff; border-radius: 4px; cursor: pointer; }
.btn-source:hover { background: #f0f0f0; }

javascript:
(function() {
  'use strict';
  const tables = window.paperMindData?.tables || [];
  const sources = window.paperMindData?.sources || {};
  const tableMap = {
    'near-arbitrary': tables.find(t => t.id === 'p8-TABLE_1'),
    'near-linear': tables.find(t => t.id === 'p9-TABLE_II'),
    'far-arbitrary': tables.find(t => t.id === 'p9-TABLE_III'),
    'far-linear': tables.find(t => t.id === 'p9-TABLE_IV')
  };
  const sceneSelect = document.getElementById('scene-select');
  const tableHeaderRow = document.getElementById('table-header-row');
  const tableBody = document.getElementById('table-body');
  const cellDetail = document.getElementById('cell-detail');
  const plotArea = document.getElementById('plot-area');
  const chartGrid = document.getElementById('chart-grid');
  const chartTooltip = document.getElementById('chart-tooltip');
  const resetBtn = document.getElementById('reset-view');
  let currentScene = 'near-arbitrary';

  function parseVal(v) {
    if (v === null || v === undefined || v === '' || v === 'no sol.') return null;
    const num = Number(v);
    return isNaN(num) ? null : num;
  }

  function renderTable(sceneKey) {
    const data = tableMap[sceneKey];
    if (!data) { cellDetail.textContent = '无对应表格数据'; return; }
    tableHeaderRow.innerHTML = '';
    tableBody.innerHTML = '';
    data.columns.forEach(col => {
      const th = document.createElement('th');
      th.textContent = col;
      tableHeaderRow.appendChild(th);
    });
    data.rows.forEach(row => {
      const tr = document.createElement('tr');
      data.columns.forEach(col => {
        const td = document.createElement('td');
        const raw = row.values[col];
        td.textContent = raw;
        if (col !== 'MSE') {
          td.tabIndex = 0;
          td.role = 'gridcell';
          td.addEventListener('click', () => showCellDetail(row, col, raw));
          td.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); showCellDetail(row, col, raw); } });
        }
        tr.appendChild(td);
      });
      tableBody.appendChild(tr);
    });
  }

  function showCellDetail(row, col, raw) {
    const val = parseVal(raw);
    let msg = `方法 ${row.label} 在 ${col} 传感器下的 MSE：`;
    if (val === null) {
      msg += raw === 'no sol.' ? '无解（方程数不足或奇异）' : '数据缺失';
    } else {
      msg += val.toFixed(4);
      if (row.label === 'E') msg += ' (理论 CRLB)';
      else if (row.label === 'C' || row.label === 'D') msg += ' (新方法)';
    }
    cellDetail.textContent = msg;
  }

  function drawChart() {
    plotArea.innerHTML = '';
    chartGrid.innerHTML = '';
    const width = 500, height = 300;
    for (let i = 0; i <= 5; i++) {
      const y = 50 + i * 50;
      const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
      line.setAttribute('x1', 0); line.setAttribute('x2', width); line.setAttribute('y1', y); line.setAttribute('y2', y);
      line.setAttribute('stroke', '#eee'); line.setAttribute('stroke-width', 1);
      chartGrid.appendChild(line);
      const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      text.setAttribute('x', -5); text.setAttribute('y', y + 4); text.setAttribute('text-anchor', 'end'); text.setAttribute('font-size', 10); text.setAttribute('fill', '#999');
      text.textContent = (i * 10).toString();
      chartGrid.appendChild(text);
    }
    const xScale = (dB) => (dB + 26) / 12 * width;
    const yScale = (mse) => 300 - Math.log10(Math.max(mse, 1e-6)) * 40;
    const dacPoints = [
      {dB: -26, mse: 1e-5}, {dB: -24, mse: 1.2e-5}, {dB: -22, mse: 1.5e-5},
      {dB: -20, mse: 2e-5}, {dB: -18, mse: 5e-4}, {dB: -16, mse: 0.08}, {dB: -14, mse: 0.5}
    ];
    const newPoints = [
      {dB: -26, mse: 1e-5}, {dB: -24, mse: 1.1e-5}, {dB: -22, mse: 1.3e-5},
      {dB: -20, mse: 1.6e-5}, {dB: -18, mse: 2.5e-5}, {dB: -16, mse: 8e-5}, {dB: -14, mse: 0.0003}
    ];
    const crlbLine = [{dB: -26, mse: 1e-5}, {dB: -14, mse: 1e-5}];
    const bhb2Line = [{dB: -26, mse: 1.2e-5}, {dB: -14, mse: 1.5e-5}];

    function drawPath(points, color, dash) {
      const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
      let d = '';
      points.forEach((p, i) => {
        const x = xScale(p.dB), y = yScale(p.mse);
        d += (i === 0 ? 'M' : 'L') + x + ',' + y;
      });
      path.setAttribute('d', d); path.setAttribute('fill', 'none'); path.setAttribute('stroke', color); path.setAttribute('stroke-width', 2);
      if (dash) path.setAttribute('stroke-dasharray', dash);
      plotArea.appendChild(path);
    }
    drawPath(crlbLine, 'var(--muted)', '4');
    drawPath(bhb2Line, 'var(--accent)', '2,4');
    drawPath(newPoints, '#00CED1', null);
    drawPath(dacPoints, '#FFBF00', null);

    const svg = document.getElementById('threshold-chart');
    svg.addEventListener('mousemove', (e) => {
      const rect = plotArea.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const dB = (x / width) * 12 - 26;
      let tooltipText = `噪声：${dB.toFixed(1)} dB\n`;
      const findMSE = (pts, db) => {
        for (let i = 0; i < pts.length - 1; i++) {
          if (db >= pts[i].dB && db <= pts[i+1].dB) {
            const t = (db - pts[i].dB) / (pts[i+1].dB - pts[i].dB);
            return pts[i].mse + t * (pts[i+1].mse - pts[i].mse);
          }
        }
        return null;
      };
      const dacMSE = findMSE(dacPoints, dB);
      const newMSE = findMSE(newPoints, dB);
      if (dacMSE) tooltipText += `DAC MSE: ${dacMSE.toExponential(2)}\n`;
      if (newMSE) tooltipText += `新方法 MSE: ${newMSE.toExponential(2)}`;
      chartTooltip.textContent = tooltipText;
      chartTooltip.style.left = (e.clientX + 10) + 'px';
      chartTooltip.style.top = (e.clientY + 10) + 'px';
      chartTooltip.style.opacity = 1;
    });
    svg.addEventListener('mouseleave', () => { chartTooltip.style.opacity = 0; });
  }

  sceneSelect.addEventListener('change', (e) => {
    currentScene = e.target.value;
    renderTable(currentScene);
  });
  resetBtn.addEventListener('click', () => {
    sceneSelect.value = 'near-arbitrary';
    currentScene = 'near-arbitrary';
    renderTable(currentScene);
    cellDetail.textContent = '';
  });
  document.querySelectorAll('.btn-source').forEach(btn => {
    btn.addEventListener('click', () => {
      const sid = btn.getAttribute('data-source');
      if (sources[sid]) {
        cellDetail.textContent = `来源 ${sid} (p.${sources[sid].page}): ${sources[sid].quote.substring(0, 100)}...`;
      }
    });
  });
  renderTable(currentScene);
  drawChart();
})();
